const body = $json.body || $json;

const eventId = body.eventId || null;
const eventCreated = body.eventCreated || null;
const storeId = body.storeId || null;
const eventType = body.eventType || null;
const data = body.data || {};

const ecwidEntityId = body.entityId || null;      // numeric API order id
const orderCode = data.orderId || null;           // short human-facing order code
const oldPaymentStatus = data.oldPaymentStatus || null;
const newPaymentStatus = data.newPaymentStatus || null;
const oldFulfillmentStatus = data.oldFulfillmentStatus || null;
const newFulfillmentStatus = data.newFulfillmentStatus || null;

/*
  Process when:
  - event is order.created or order.updated
  - numeric entity id exists
  - payment is awaiting payment

  This keeps the workflow aligned to your current unpaid-order intake flow.
*/
/* Only trigger on new awaiting payment */
const shouldProcess =
  (
    eventType === 'order.created' &&
    !!ecwidEntityId &&
    newPaymentStatus === 'AWAITING_PAYMENT'
  ) ||
  (
    eventType === 'order.updated' &&
    !!ecwidEntityId &&
    newPaymentStatus === 'AWAITING_PAYMENT' &&
    oldPaymentStatus !== newPaymentStatus
  );

/*
const shouldProcess =
  ['order.created', 'order.updated'].includes(eventType) &&
  !!ecwidEntityId &&
  newPaymentStatus === 'AWAITING_PAYMENT';
*/

return [{
  json: {
    eventId,
    eventCreated,
    storeId,
    eventType,
    ecwid_entity_id: String(ecwidEntityId || ''),
    order_code: String(orderCode || ''),
    oldPaymentStatus,
    newPaymentStatus,
    oldFulfillmentStatus,
    newFulfillmentStatus,
    shouldProcess,
    raw_body: body
  }
}];

const order = $json;
const webhook = $('Code - Validate / Filter Webhook').first().json;
const items = order.items || order.orderItems || [];

const skuSet = new Set();
for (const item of items) {
  const sku = String(item?.sku || item?.SKU || '').trim();
  if (sku) skuSet.add(sku);
}
const skuList = Array.from(skuSet).join(', ') || null;

function isoOrNull(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

const billing = order.billingPerson || {};
const shipping = order.shippingPerson || {};
const customerName =
  billing.name ||
  shipping.name ||
  `${billing.firstName || ''} ${billing.lastName || ''}`.trim() ||
  `${shipping.firstName || ''} ${shipping.lastName || ''}`.trim() ||
  null;

const customerEmail = billing.email || shipping.email || order.email || null;

// numeric Ecwid entity/API id
const ecwidEntityId = String(order.id || webhook.ecwid_entity_id || '');

// short human-facing code
const orderCode = String(order.orderNumber || webhook.order_code || '');

return [{
  json: {
    ecwid_order_id: ecwidEntityId,
    order_number: Number(order.id || webhook.ecwid_entity_id || 0) || null,
    order_code: orderCode || null,
    name: `#${orderCode || ecwidEntityId}${customerName ? ' – ' + customerName : ''}`,
    status: order.fulfillmentStatus || 'AWAITING_PROCESSING',
    payment_status: order.paymentStatus || webhook.newPaymentStatus || null,
    payment_method: order.paymentMethod || null,
    order_date: isoOrNull(order.createDate || order.created || order.dateCreated || webhook.eventCreated * 1000),
    customer_name: customerName,
    customer_email: customerEmail,
    items_json: JSON.stringify(items, null, 2),
    ecwid_skus: skuList,
    provider: 'ecwid',
    site_key: 'dank_mushrooms',
    external_order_id: ecwidEntityId || null,
    external_skus: skuList,
    subtotal: Number(order.subtotal ?? order.subtotalWithoutTax ?? 0),
    tax_total: Number(order.tax ?? 0),
    order_total: Number(order.total ?? 0),
    currency: order.currency || order.currencyCode || 'USD',
    ecwid_event_type: webhook.eventType,
    ecwid_event_id: webhook.eventId,
    last_webhook_at: isoOrNull((webhook.eventCreated || 0) * 1000) || new Date().toISOString(),
    clover_reconciliation_status: 'pending',
    clover_payment_id: null,
    clover_payment_amount: null,
    clover_payment_time: null,
    clover_match_confidence: null,
    reconciled_at: null,
    reconciliation_notes: null
  }
}];

const payload = JSON.stringify($json);
return [{
  json: {
    payload_base64: Buffer.from(payload, 'utf8').toString('base64'),
    ecwid_order_id: $json.ecwid_order_id,
    ecwid_event_id: $json.ecwid_event_id
  }
}];
